from pathlib import Path
import base64,zlib,re

def _d(s): return zlib.decompress(base64.b64decode(s)).decode('utf-8')
CHART_TREND=''
CUSTOMER_CHART=''
MONTHLY_TREND=''
CHARTS_FILE=''
CHANGELOG=''

def _replace_block(text,start_marker,end_marker,new_block):
    if start_marker not in text or end_marker not in text: return text
    a=text.index(start_marker); b=text.index(end_marker,a)
    return text[:a]+new_block+text[b:]

def apply_patch(root):
    root=Path(root)
    constants=root/'src/constants.py'; analytics=root/'src/analytics.py'; ui=root/'src/ui.py'; charts=root/'src/charts.py'
    try:
        if constants.exists() and "APP_VERSION = '0.1.9'" in constants.read_text(encoding='utf-8') and charts.exists(): return
    except Exception: pass
    if constants.exists():
        s=constants.read_text(encoding='utf-8')
        s=re.sub(r"APP_VERSION\s*=\s*'[^']+'","APP_VERSION = '0.1.9'",s,count=1)
        constants.write_text(s,encoding='utf-8')
    if analytics.exists():
        s=analytics.read_text(encoding='utf-8')
        if 'MONTH_SHORT_NAMES' not in s:
            s=s.replace("MONTH_NAMES = ['Leden','Únor','Březen','Duben','Květen','Červen','Červenec','Srpen','Září','Říjen','Listopad','Prosinec']\n","MONTH_NAMES = ['Leden','Únor','Březen','Duben','Květen','Červen','Červenec','Srpen','Září','Říjen','Listopad','Prosinec']\nMONTH_SHORT_NAMES = ['Led','Úno','Bře','Dub','Kvě','Čvn','Čvc','Srp','Zář','Říj','Lis','Pro']\n")
        s=_replace_block(s,'    def monthly_trend(self, year):','\n    def salespeople',_d(MONTHLY_TREND))
        analytics.write_text(s,encoding='utf-8')
    charts.write_text(_d(CHARTS_FILE),encoding='utf-8')
    if ui.exists():
        s=ui.read_text(encoding='utf-8')
        if 'from .charts import BusinessChart' not in s:
            s=s.replace('from .analytics import Analytics, MONTH_NAMES\n','from .analytics import Analytics, MONTH_NAMES\nfrom .charts import BusinessChart\n',1)
        s=_replace_block(s,'    def chart_trend(self,parent,year):','\n    def chart_margin',_d(CHART_TREND))
        s=_replace_block(s,'    def chart_customer_history(self,parent,history):','\n    def product_compact',_d(CUSTOMER_CHART))
        s=s.replace("else: messagebox.showinfo('Aktualizace','Používáte aktuální verzi '+r.get('current',APP_VERSION)+'.')","else: messagebox.showinfo('Aktualizace',f\"Verze je aktuální.\\n\\nPoužíváte nejnovější verzi {r.get('current',APP_VERSION)}.\")")
        ui.write_text(s,encoding='utf-8')
    (root/'ZMENY_0.1.9.txt').write_text(_d(CHANGELOG),encoding='utf-8')
